function driveNewFileEvents({ events }) {
  if (!Array.isArray(events)) throw new Error("Expected a Google Drive event batch");
  const seen = new Set();
  const files = events.map((event) => {
    if (
      !event ||
      event.eventType !== "file_created" ||
      event.itemType !== "file" ||
      typeof event.fileId !== "string" ||
      !event.fileId ||
      typeof event.name !== "string"
    )
      throw new Error("Expected a complete new-file event");
    if (seen.has(event.fileId)) throw new Error("Duplicate Google Drive file in this batch");
    seen.add(event.fileId);
    return { fileId: event.fileId, name: event.name };
  });
  return { files };
}

const items = $input.all();
const files = driveNewFileEvents({
  events: items.map((item) => ({
    eventType: "file_created",
    itemType: "file",
    fileId: item.json.id,
    name: item.json.name,
  })),
}).files;
return files.map((file, index) => ({ json: file, pairedItem: { item: index } }));

if (
  !Array.isArray($json.accepted) ||
  !$json.accepted.length ||
  $json.accepted.some((value) => typeof value !== "string" || !value.trim()) ||
  ($json.messageId != null && typeof $json.messageId !== "string") ||
  !Array.isArray($json.rejected) ||
  $json.rejected.length ||
  typeof $json.response !== "string"
)
  throw new Error("SMTP did not confirm the file notification");
return {
  json: {
    fileId: $("Validate new files").item.json.fileId,
    messageId: $json.messageId ?? null,
    accepted: $json.accepted,
    rejected: $json.rejected,
    response: $json.response,
  },
};
